package cm.naxa.naxasecurity
import androidx.compose.material3.*
import androidx.compose.runtime.*
private val helpEntries=listOf("Comment accéder à mon site ?" to "Connectez-vous avec votre compte individuel, puis sélectionnez un site autorisé. Contactez votre administrateur si le site manque.","Comment signaler un incident ?" to "Ouvrez le dossier incident, renseignez les faits et transmettez-le. En danger immédiat, appliquez le plan local et contactez les secours compétents.","Comment fonctionne le pointage ?" to "Déclarez l’arrivée ou le départ dans Présence. Une déclaration peut nécessiter un examen ; elle ne constitue pas une preuve certifiée.","Comment ouvrir un ticket ?" to "Dans Livecare, choisissez Création de ticket puis une catégorie et une description. Consultez ensuite le suivi.","Les alarmes incendie dépendent-elles de NAXA ?" to "Non. La centrale locale reste indépendante. NAXA ne remplace pas les équipements réglementaires ni les consignes d’évacuation.","Comment gérer les notifications ?" to "Dans Préférences de notifications, choisissez vos canaux. Les alertes internes fonctionnent indépendamment des canaux externes non raccordés.")
@Composable internal fun SecurityHelp(screen:String){if(screen !in setOf("B6.05","B6.06"))return;var q by remember(screen){mutableStateOf("")};val terms=q.trim().split(Regex("\\s+")).filter{it.isNotBlank()};val hits=helpEntries.filter{e->terms.all{(e.first+" "+e.second).contains(it,true)}};Text("Questions fréquentes — recherche guidée, sans IA générative");OutlinedTextField(q,{q=it},label={Text("Rechercher")});hits.forEach{(question,answer)->var opened by remember(question){mutableStateOf(false)};TextButton(onClick={opened=!opened}){Text(question)};if(opened)Text(answer)};if(hits.isEmpty())Text("Aucune réponse trouvée. Créez un ticket Livecare.")}